package autocomplete

import (
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/SCKelemen/clix/v2"
)

// Directives end the output of the completion command. They tell the
// shell script whether file names are expected when no candidate is
// printed.
const (
	directiveFiles   = ":files"
	directiveNoFiles = ":nofiles"
)

// NewCompleteCommand returns the hidden "__complete" command that the
// scripts generated by the autocomplete command call on every completion.
// The Extension adds it, and so does NewAutocompleteCommand when the app
// has a root command; add it yourself only if you build the root after
// creating the autocomplete command.
//
// It prints the candidates for the word being completed, computed from
// the live command tree, so completion always matches the installed
// program: child commands and aliases (never hidden ones), the flags in
// scope (those of the command, its ancestors and the root, as the parser
// resolves them, leaving out flags already given), and values from
// completion hooks (see clix.FlagSet.SetCompletion).
//
// The protocol, which the generated scripts implement, is
//
//	app __complete --shell <bash|zsh|fish|powershell> --cur=<word> -- <program> <words...>
//
// where <words...> are the words before the one being completed, with
// shell quoting removed, and --cur is the word being completed (always
// written with "=", so that an empty word is still an argument). bash
// passes "--line=<command line up to the cursor>" instead of the words,
// and --cur is then the part of the word that readline replaces (its $2),
// which can be shorter because readline breaks words at "=" and ":".
// PowerShell passes each word as --word=<word>, because Windows
// PowerShell drops empty arguments and may drop "--".
//
// It prints one candidate per line, formatted for the shell, followed by a
// directive line: ":files" when a file name is expected and nothing more
// specific is known, ":nofiles" otherwise. Without --shell, each line is
// "value<TAB>description".
func NewCompleteCommand(app *clix.App) *clix.Command {
	cmd := clix.NewCommand(completeName)
	cmd.Short = "Print shell completion candidates (used by completion scripts)"
	cmd.Hidden = true
	cmd.IsExtensionCommand = true
	// Completion must keep working while the config file is broken.
	clix.AllowConfigErrors(cmd)

	var shell, cur, line string
	var words []string
	cmd.Flags.StringVar(clix.StringVarOptions{
		FlagOptions: clix.FlagOptions{Name: "shell", Usage: "Output format: bash, zsh, fish or powershell"},
		Value:       &shell,
	})
	cmd.Flags.StringVar(clix.StringVarOptions{
		FlagOptions: clix.FlagOptions{Name: "cur", Usage: "The word being completed"},
		Value:       &cur,
	})
	cmd.Flags.StringVar(clix.StringVarOptions{
		FlagOptions: clix.FlagOptions{Name: "line", Usage: "The command line up to the cursor (bash)"},
		Value:       &line,
	})
	cmd.Flags.ArgsVar(clix.ArgsVarOptions{
		Name:  "word",
		Usage: "The program name and the words before the one being completed",
		Value: &words,
	})

	cmd.Run = func(ctx *clix.Context) error {
		// Only values from the command line count: an environment variable
		// or config key that happens to share a flag's name must not change
		// what is completed.
		given := func(name string) bool { return cmd.Flags.Changed(name) }
		if !given("shell") {
			shell = ""
		}
		if !given("cur") {
			cur = ""
		}
		format, err := normalizeShell(shell, true)
		if err != nil {
			return err
		}

		var typed []string
		var bash *bashWord
		if given("line") {
			var ok bool
			if typed, cur, bash, ok = splitBashLine(line, cur); !ok {
				// Only the program name is being typed.
				_, err = io.WriteString(output(app), render(format, result{}, bash))
				return err
			}
		} else if given("word") && len(words) > 0 {
			typed = words[1:] // skip the program name
		}
		switch format {
		case "fish":
			cur = unquoteFish(cur)
		case "powershell":
			cur = unquotePowerShell(cur)
		}

		res := newEngine(ctx.Context, app).complete(typed, cur)
		_, err = io.WriteString(output(app), render(format, res, bash))
		return err
	}
	return cmd
}

// normalizeShell returns the canonical name of shell. An empty name is
// allowed (the plain format) only when plain is set.
func normalizeShell(shell string, plain bool) (string, error) {
	switch s := strings.ToLower(strings.TrimSpace(shell)); s {
	case "bash", "zsh", "fish":
		return s, nil
	case "powershell", "pwsh":
		return "powershell", nil
	case "":
		if plain {
			return "", nil
		}
	}
	return "", fmt.Errorf("unsupported shell: %s (want bash, zsh, fish or powershell)", shell)
}

// bashWord describes the part of the current word that readline replaces.
type bashWord struct {
	keep  string // the unquoted text of the word before the replaced part
	quote byte   // the quote state where the replaced part starts
}

// splitBashLine splits bash's command line (up to the cursor) into the
// words before the current one, without the program name, and the
// current word. replaced is readline's word ($2 of the completion
// function), the end of the line that a candidate replaces. It reports
// false when the line holds only the program name being typed.
func splitBashLine(line, replaced string) (typed []string, cur string, bw *bashWord, ok bool) {
	words := splitPOSIX(line)
	if len(words) < 2 {
		return nil, "", &bashWord{}, false
	}
	last := words[len(words)-1]
	for _, w := range words[1 : len(words)-1] {
		typed = append(typed, w.value)
	}
	bw = &bashWord{}
	if strings.HasSuffix(last.raw, replaced) {
		bw.keep, bw.quote = unquotePOSIXPrefix(last.raw[:len(last.raw)-len(replaced)])
	}
	return typed, last.value, bw, true
}

// render formats res for shell, one candidate per line, followed by the
// directive.
func render(shell string, res result, bw *bashWord) string {
	var b strings.Builder
	seen := map[string]bool{}
	for _, c := range res.candidates {
		if c.Value == "" || hasControl(c.Value) {
			continue
		}
		desc := strings.TrimSpace(singleLine(c.Description))
		var line string
		switch shell {
		case "bash":
			v := c.Value
			if bw != nil {
				if !strings.HasPrefix(v, bw.keep) {
					continue
				}
				v = v[len(bw.keep):]
				if v == "" {
					continue
				}
				line = quoteBash(v, bw.quote)
			} else {
				line = quoteBash(v, unquoted)
			}
		case "zsh":
			line = zshDescribe(c.Value, desc)
		case "powershell":
			tip := desc
			if tip == "" {
				tip = c.Value
			}
			line = quotePowerShell(c.Value) + "\t" + c.Value + "\t" + tip
		default: // fish and the plain format
			line = c.Value
			if desc != "" {
				line += "\t" + desc
			}
		}
		if seen[line] {
			continue
		}
		seen[line] = true
		b.WriteString(line)
		b.WriteByte('\n')
	}
	if res.files {
		b.WriteString(directiveFiles)
	} else {
		b.WriteString(directiveNoFiles)
	}
	b.WriteByte('\n')
	return b.String()
}

// output returns the app's standard output.
func output(app *clix.App) io.Writer {
	if app.Out != nil {
		return app.Out
	}
	return os.Stdout
}
